import{_ as e,o as t,c as r,ag as o}from"./chunks/framework.DMXcdKmJ.js";const u=JSON.parse('{"title":"创建第一个工程","description":"从新建工程开始，选择初始模板，进入应用开发并查看第一次开发预览。","frontmatter":{"title":"创建第一个工程","description":"从新建工程开始，选择初始模板，进入应用开发并查看第一次开发预览。","status":"reviewed","kind":"tutorial"},"headers":[],"relativePath":"zh/start/first-project.md","filePath":"zh/快速开始/创建第一个工程.md"}'),i={name:"zh/start/first-project.md"};function n(s,a,h,p,d,l){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="创建第一个工程" tabindex="-1">创建第一个工程 <a class="header-anchor" href="#创建第一个工程" aria-label="Permalink to &quot;创建第一个工程&quot;">​</a></h1><p>本教程的目标是：创建一个自己的工程，完成源码初始化，并在开发工作区看到预览。正式发布和运行需要后续步骤。</p><p>开始前，平台应已安装、组织可正常登录，你使用的是有工程功能权限的组织账号。开发环境的部署和资源由平台管理员事先准备；本教程不要求在个人电脑另装数据库或容器。</p><h2 id="_1-进入工程管理" tabindex="-1">1. 进入工程管理 <a class="header-anchor" href="#_1-进入工程管理" aria-label="Permalink to &quot;1. 进入工程管理&quot;">​</a></h2><p>从公共入口选择正确组织并登录，打开“工程管理”。</p><p>没有工程管理入口时，先让组织管理员确认角色。显示读取失败时先重试，不把空白画面当成需要重新安装平台。</p><h2 id="_2-新建一个工程" tabindex="-1">2. 新建一个工程 <a class="header-anchor" href="#_2-新建一个工程" aria-label="Permalink to &quot;2. 新建一个工程&quot;">​</a></h2><p>点击 <strong>“新建工程”</strong>，输入便于识别的名称，例如“我的第一个工程”；这是示例名称，请按实际情况填写。描述可以简单写明用途。</p><p>点击 <strong>“创建”</strong>，等待成功，在工程列表确认新工程。请求结果不明确时先搜索核对，不连续新建同名工程。</p><p>新工程默认私有；需要同组织协作时，再按<a href="/induframe-docs/zh/guide/projects.html">工程管理</a>确认共享范围和权限。</p><p><strong>做到这里</strong>：工程记录已经存在，但源码可能还未初始化。</p><h2 id="_3-打开应用开发并选择模板" tabindex="-1">3. 打开应用开发并选择模板 <a class="header-anchor" href="#_3-打开应用开发并选择模板" aria-label="Permalink to &quot;3. 打开应用开发并选择模板&quot;">​</a></h2><p>在这个工程打开 <strong>“应用开发”</strong>。若系统已自动打开，直接继续。</p><p>第一次会看到“选择工程技术栈”，提供 Vue、React 与 JavaScript、TypeScript 的模板组合。按团队安排选择；没有约定时先确认页面选项，再点击该页面的 <strong>“创建工程”</strong>。</p><p>这里是在已有工程里生成初始源码，不是再次在组织中创建同名工程。初始化完成后，不通过反复重选模板切换技术栈。</p><p><strong>做到这里</strong>：工作区能够显示 AI、编辑器和页面等工具。暂未就绪时等待服务状态，不反复启停。</p><h2 id="_4-保存修改并查看页面" tabindex="-1">4. 保存修改并查看页面 <a class="header-anchor" href="#_4-保存修改并查看页面" aria-label="Permalink to &quot;4. 保存修改并查看页面&quot;">​</a></h2><p>进入“编辑器”查看源码，或通过 AI 协助修改。保存更改后，选择 **“页面”**查看预览；需要时按提示启动预览服务。</p><p>第一次使用 AI，先看<a href="/induframe-docs/zh/guide/ai-development.html">AI 助手操作说明</a>，确认模型、工具范围和任务，再检查实际修改。</p><p>页面需要登录或数据权限时，使用合适的工程用户。预览工具的身份选择与组织登录不同，详细操作见<a href="/induframe-docs/zh/guide/preview.html">预览工程页面</a>。</p><p><strong>做到这里</strong>：能够看到当前工程的开发页面，并知道怎样保存和检查更改。仍需按用途核对实际交互与数据结果。</p><h2 id="_5-结束这次操作" tabindex="-1">5. 结束这次操作 <a class="header-anchor" href="#_5-结束这次操作" aria-label="Permalink to &quot;5. 结束这次操作&quot;">​</a></h2><p>保存未保存内容。需要暂停整个开发环境时，先通知共同使用者，再按<a href="/induframe-docs/zh/guide/workspace.html">工作区说明</a>确认停止；只想重新加载画面时用预览“刷新”。</p><p>不要用删除工程代替停止开发环境。</p><h2 id="接下来做什么" tabindex="-1">接下来做什么 <a class="header-anchor" href="#接下来做什么" aria-label="Permalink to &quot;接下来做什么&quot;">​</a></h2><ul><li>需要管理其他工程、标签或分组：看<a href="/induframe-docs/zh/guide/projects.html">创建和管理工程</a>。</li><li>需要上传资料：看<a href="/induframe-docs/zh/guide/project-files.html">查看和上传工程文件</a>。</li><li>需要接入业务数据：从<a href="/induframe-docs/zh/guide/datacenter.html">认识数据中心</a>开始。</li><li>准备正式使用：先理解<a href="/induframe-docs/zh/concepts/development-and-runtime.html">开发、发布与运行</a>，再按交付安排完成相应配置和部署。</li></ul><p>遇到配额、权限、初始化或预览错误时，保存工程名称和页面提示，请管理员核对；不要为绕过错误关闭安全检查或删除已有工程。</p>',27)])])}const _=e(i,[["render",n]]);export{u as __pageData,_ as default};
